import type { DrillResult } from "./harness";
import type { NaiveResult } from "./naive";

type Full = DrillResult & { baseline?: NaiveResult };

const sum = (xs: number[]) => xs.reduce((a, b) => a + b, 0);
const pct = (x: number) => `${(100 * x).toFixed(1)}%`;

export function markdown(results: Full[]): string {
  const L: string[] = [
    "# Fault drills",
    "",
    "Generated by `bun run drill`. Each drill runs the real worker processes, scheduler, analytics shipper and webhook deliverer against the provider simulator with injected faults, then judges the outcome from the simulator's request ledger, Postgres, ClickHouse and the simulator's answer key. Where a drill has a baseline, the same world and faults are run through the naive worker described in `src/drills/naive.ts` at the same concurrency.",
    "",
    "## Summary",
    "",
    "| Drill | Runs | Collected | Failed (reported) | Skipped for budget | Not finished | Customer-visible duplicates | Self-inflicted 429s | Calls per run, worst provider | Max budget overrun |",
    "|---|---|---|---|---|---|---|---|---|---|",
  ];
  for (const r of results) {
    const m = r.measures;
    const failed = sum(Object.values(m.runs.failed));
    const s429 = sum(Object.values(m.providers).map((p) => p.over_limit_429));
    const worst = Math.max(...Object.values(m.providers).map((p) => p.per_run));
    L.push(
      `| ${r.spec.name} | ${m.runs.expected} | ${m.runs.succeeded} | ${failed} | ${m.runs.skipped_budget} | **${m.runs.not_finished}** | **${m.analytics.customer_visible_duplicates}** | ${s429} | ${worst.toFixed(2)} | €${m.cost.max_budget_overrun_eur.toFixed(2)} |`,
    );
    if (r.baseline) {
      const b = r.baseline;
      const b429 = sum(Object.values(b.providers).map((p) => p.over_limit_429));
      const bworst = Math.max(...Object.values(b.providers).map((p) => p.per_run));
      L.push(
        `| *naive baseline* | ${b.runs} | ${b.stored_runs} | ${b.failed} | ${b.skipped_budget} | **${b.lost}** (lost) | **${b.duplicate_rows}** | ${b429} | ${bworst.toFixed(2)} | €${b.max_budget_overrun_eur.toFixed(2)} |`,
      );
    }
  }
  L.push("");
  for (const r of results) {
    const m = r.measures;
    L.push(`## ${r.spec.name}: ${r.spec.title}`, "", `*${r.spec.question}*`, "");
    L.push(
      `Finished in ${r.seconds.toFixed(1)} s${r.timedOut ? " (**timed out**)" : ""}; worker processes restarted: ${r.workerRestarts}.`,
      "",
    );
    L.push("| Provider | Calls | Calls per run | 429s we caused | Calls while it was down | Answers |", "|---|---|---|---|---|---|");
    for (const [p, s] of Object.entries(m.providers).sort())
      L.push(`| ${p} | ${s.requests} | ${s.per_run.toFixed(2)} | ${s.over_limit_429} | ${s.during_outage} | ${s.ok} |`);
    if (r.baseline) {
      L.push(
        "",
        "Naive baseline, same faults:",
        "",
        "| Provider | Calls | Calls per run | 429s caused | Calls while it was down |",
        "|---|---|---|---|---|",
      );
      for (const [p, s] of Object.entries(r.baseline.providers).sort())
        L.push(`| ${p} | ${s.requests} | ${s.per_run.toFixed(2)} | ${s.over_limit_429} | ${s.during_outage} |`);
    }
    const failed = Object.entries(m.runs.failed).map(([k, v]) => `${v} ${k}`);
    L.push(
      "",
      `- Runs: ${m.runs.succeeded} collected of ${m.runs.expected}; failed and reported: ${failed.length ? failed.join(", ") : "none"}; skipped for budget: ${m.runs.skipped_budget}; **not finished: ${m.runs.not_finished}**.`,
      `- ClickHouse: ${m.analytics.distinct_runs} runs, ${m.analytics.raw_rows_before_merge} raw rows before merges, **${m.analytics.customer_visible_duplicates} duplicates visible to customers**, ${m.analytics.succeeded_not_in_clickhouse} collected runs missing.`,
      `- Cost: provider billed €${m.cost.provider_billed_eur.toFixed(3)}, our ledger €${m.cost.ledger_eur.toFixed(3)}; projects over budget: ${m.cost.projects_over_budget} (max overrun €${m.cost.max_budget_overrun_eur.toFixed(3)}).`,
      `- Extraction against the answer key (${m.extraction.runs_scored} answers): mentions precision ${pct(m.extraction.mention_precision)}, recall ${pct(m.extraction.mention_recall)}; position exact ${pct(m.extraction.position_exact)}; citations precision ${pct(m.extraction.citation_precision)}, recall ${pct(m.extraction.citation_recall)}.`,
      `- Freshness, scheduled to visible in ClickHouse: p50 ${m.freshness_s.p50.toFixed(2)} s, p95 ${m.freshness_s.p95.toFixed(2)} s, max ${m.freshness_s.max.toFixed(2)} s.`,
      `- Webhooks: ${m.webhooks.events} events, ${m.webhooks.received_unique} received, **${m.webhooks.missing} missing**, ${m.webhooks.duplicate_deliveries} duplicate deliveries (receivers dedupe on webhook-id), ${m.webhooks.bad_signatures} bad signatures.`,
    );
    if (r.reparse)
      L.push(
        `- Quarantine: ${r.reparse.resolved} drifted answers completed from stored bodies after the parser fix, ${r.reparse.still_unknown} still unknown; open now: ${m.quarantine.open}.`,
      );
    L.push("");
  }
  return `${L.join("\n")}\n`;
}
